insert into public.destinations (slug, name, category, city, region, latitude, longitude, radius_m, popularity, short_description, description, history, culture, significance, local_customs, food, shopping, tips, opening_hours, entry_fee, best_time, is_landmark) values
  ('badshahi-mosque', 'Badshahi Mosque', 'religious', 'Lahore', 'Punjab', 31.5881, 74.3107, 1000, 98, 'A grand Mughal-era mosque of red sandstone facing the Lahore Fort.', 'Built of red sandstone with white marble domes, the Badshahi Mosque is one of the largest mosques in the world and the crown of Lahore''s Walled City skyline. Its vast courtyard can hold tens of thousands of worshippers.', 'Commissioned by the Mughal emperor Aurangzeb and completed in 1673, the mosque was the largest in the world for over three centuries. It was used as a garrison during Sikh rule and later restored under British and Pakistani administration.', 'The mosque sits within the Hazuri Bagh complex alongside the Lahore Fort, the Roshnai Gate and the tomb of the poet Allama Iqbal.', 'It is a symbol of Mughal architectural ambition and of Lahore''s identity, and remains an active place of worship.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times.', 'Fort Road Food Street next door serves karahi, tikka and lassi with views of the minarets at night.', 'Look for embroidered shawls and miniature-painting souvenirs in the Walled City lanes nearby.', 'Visit late afternoon for golden light on the sandstone, then stay for the illuminated view after sunset.', 'Open daily, roughly sunrise to after Isha prayer; tourist access is limited during Friday prayers.', 'Free entry; shoe-keeping attendants expect a small tip.', 'October to March', true),
  ('lahore-fort', 'Lahore Fort (Shahi Qila)', 'historical', 'Lahore', 'Punjab', 31.5885, 74.3153, 800, 95, 'UNESCO World Heritage citadel with Mughal palaces, halls and the Sheesh Mahal.', 'The Lahore Fort is a sprawling citadel of palaces, audience halls, gardens and gateways spanning several Mughal reigns. Highlights include the mirror-mosaic Sheesh Mahal, the Picture Wall and the Alamgiri Gate.', 'Rebuilt in its current form by Emperor Akbar in the 16th century and expanded by Jahangir, Shah Jahan and Aurangzeb. It was inscribed as a UNESCO World Heritage Site together with the Shalimar Gardens in 1981.', 'The fort showcases Mughal tile mosaics, fresco work and pietra dura inlay, with Persian, Hindu and Central Asian influences.', 'It is among the most complete records of Mughal court life in South Asia.', 'Some halls require separate tickets; photography with a tripod may need permission.', 'Try the street food of Fort Road and Gawalmandi after your visit.', 'Handicraft stalls near the fort entrance sell khussa shoes and replica tiles.', 'Allow at least two hours; wear comfortable shoes for the ramps and stone paths.', 'Daily, about 8:30 AM to 5:00 PM (seasonal variation).', 'Ticketed; foreign visitors pay a higher rate.', 'October to March', true),
  ('minar-e-pakistan', 'Minar-e-Pakistan', 'historical', 'Lahore', 'Punjab', 31.5925, 74.3095, 500, 90, 'National monument marking the 1940 Lahore Resolution, set in Greater Iqbal Park.', 'A tall tower of concrete and marble rising above Greater Iqbal Park, Minar-e-Pakistan commemorates the resolution that called for a separate homeland for the Muslims of South Asia.', 'Built between 1960 and 1968 on the spot where the All-India Muslim League passed the Lahore Resolution on 23 March 1940.', 'The base is shaped like a flower and carries inscriptions of the resolution text and national verses in Urdu, Bengali and English.', 'It is a central symbol of the founding of Pakistan and a gathering place on national days.', 'Families picnic in the park in the evening; respect the monument area.', 'Stalls around Iqbal Park sell roasted corn, chaat and fresh juices.', 'Small vendors sell flags and national souvenirs around Pakistan Day.', 'The surrounding park has fountains and walking tracks; it gets busy on public holidays.', 'Park open daily from morning to late evening.', 'Small park entry fee.', 'Evenings, October to March', true),
  ('fort-road-food-street', 'Fort Road Food Street', 'food', 'Lahore', 'Punjab', 31.5869, 74.3122, 300, 88, 'Restored havelis turned rooftop restaurants with views of the Badshahi Mosque.', 'A pedestrian street of restored old buildings whose rooftops overlook the Badshahi Mosque. It is one of the most atmospheric places to try traditional Lahori cuisine at night.', 'The street was restored as a heritage food destination, reviving colonial and Mughal-era facades of the Walled City.', 'Lahoris are famous for their love of food; dinner here is a social event that runs late into the night.', 'It combines heritage, food culture and one of the best night views in the city.', 'Dinner is usually late (9 PM onwards). Ask for rooftop seating early.', 'Mutton karahi, chicken tikka, seekh kebab, paye, and sweet lassi.', 'Cushion covers and lamps decorated with truck art are sold nearby.', 'Busiest on weekends; the radius overlaps the Badshahi Mosque, ideal for testing overlapping geofences.', 'Most restaurants open from late afternoon to after midnight.', 'No entry fee; meals are mid-range.', 'Evenings, year-round', true),
  ('wazir-khan-mosque', 'Wazir Khan Mosque', 'religious', 'Lahore', 'Punjab', 31.583, 74.3236, 300, 85, 'Exquisite 17th-century mosque covered in Mughal tile mosaics and frescoes.', 'Tucked into the Walled City near Delhi Gate, the Wazir Khan Mosque is renowned for the most ornate Mughal-era faience tile work in Pakistan, with floral frescoes covering almost every surface.', 'Built in the 1630s during the reign of Shah Jahan by Ilm-ud-din Ansari, known as Wazir Khan, the governor of Lahore.', 'Its forecourt once hosted a bazaar of calligraphers and bookbinders, a tradition reflected in the shops around it.', 'It is considered a masterpiece of Mughal decorative art and has been carefully restored.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times.', 'Try the traditional sweets and halwa puri in the lanes around Delhi Gate.', 'The Shahi Guzargah (Royal Trail) has spice markets and copper-ware shops.', 'The small radius (300 m) is useful for testing precise geofences in dense streets.', 'Daily, outside prayer times for tourists.', 'Small fee for tourists.', 'October to March', true),
  ('shalimar-gardens', 'Shalimar Gardens', 'park', 'Lahore', 'Punjab', 31.5859, 74.382, 700, 84, 'Terraced Mughal pleasure gardens with fountains and marble pavilions.', 'A Persian-style garden laid out on three descending terraces with hundreds of fountains, water channels and pavilions, designed as a paradise on earth.', 'Laid out by Emperor Shah Jahan in 1641-42. Together with the Lahore Fort, the gardens are a UNESCO World Heritage Site.', 'The design follows the charbagh concept of four-part gardens symbolising paradise in Islamic tradition.', 'It is one of the finest surviving examples of Mughal garden design.', 'Picnicking is common; avoid walking on restricted lawns.', 'Snack vendors near the gate sell samosas and seasonal fruit.', 'Limited shopping; bring water.', 'Visit in spring when fountains run and flowers bloom.', 'Daily, about 8 AM to 6 PM.', 'Ticketed (low fee).', 'February to April', true),
  ('lahore-museum', 'Lahore Museum', 'museum', 'Lahore', 'Punjab', 31.5681, 74.3083, 400, 78, 'Pakistan''s oldest major museum with Gandhara art, miniatures and coins.', 'Housed in a red-brick Indo-Gothic building on The Mall, the museum holds Gandhara Buddhist sculpture, Mughal and Sikh artefacts, miniature paintings and the famous Fasting Buddha.', 'Founded in 1865 and moved to its current building in 1894; Rudyard Kipling''s father John Lockwood Kipling was an early curator.', 'The collection traces the cultural history of the region from the Indus Valley to the modern era.', 'It is the best single place to understand the deep history of Punjab and Gandhara.', 'Photography rules vary by gallery; bags may be checked.', 'Cafes on The Mall and Anarkali nearby.', 'Zamzama gun is outside; Anarkali Bazaar is a short walk away.', 'Allow two hours; the Gandhara gallery is the highlight.', 'Typically 9 AM to 5 PM, closed on some public holidays.', 'Ticketed.', 'Year-round', true),
  ('anarkali-bazaar', 'Anarkali Bazaar', 'shopping', 'Lahore', 'Punjab', 31.568, 74.31, 500, 75, 'One of South Asia''s oldest markets for fabrics, jewellery and street food.', 'A bustling bazaar of narrow lanes selling clothes, bangles, shoes, fabric and street snacks, named after the legendary Anarkali.', 'The bazaar has existed for at least two centuries and grew alongside colonial Lahore''s Mall Road.', 'Bargaining is expected and the market is busiest in the evening and before Eid.', 'It offers a lively snapshot of everyday Lahori life.', 'Bargain politely; keep valuables secure in crowds.', 'Try dahi bhallay, gol gappay and fresh falooda.', 'Embroidered fabric, khussa shoes, glass bangles and jewellery.', 'Go in the evening; avoid peak Eid rush if you dislike crowds.', 'Shops open roughly noon to 10 PM; many close on Sundays.', 'Free.', 'Evenings, year-round', true),
  ('jahangir-tomb', 'Tomb of Jahangir', 'historical', 'Lahore', 'Punjab', 31.6224, 74.3036, 1500, 72, 'Mughal emperor''s mausoleum in a walled garden across the Ravi river.', 'The mausoleum of Emperor Jahangir stands in a large garden in Shahdara, decorated with marble inlay, frescoes and four tall minarets.', 'Built in the 1630s by his son Shah Jahan. The nearby tombs of Nur Jahan and Asif Khan form a wider Mughal complex.', 'The tomb blends Persian garden design with Mughal decoration.', 'It is one of the finest Mughal tombs outside India.', 'Remove shoes where requested inside the tomb chamber.', 'Limited food nearby; eat in central Lahore.', 'Few shops; bring water.', 'Its large radius (1.5 km) is useful for testing early-warning geofences while driving.', 'Daily, about 9 AM to 5 PM.', 'Ticketed (low fee).', 'October to March', true),
  ('wagah-border', 'Wagah Border Ceremony', 'attraction', 'Lahore', 'Punjab', 31.6047, 74.5728, 1500, 80, 'Energetic daily flag-lowering ceremony at the Pakistan-India border.', 'Every evening, border guards perform a high-energy flag-lowering ceremony with synchronised marching while crowds cheer from the stands.', 'The ceremony has been held at the Wagah-Attari crossing since 1959.', 'Spectators wave flags and chant patriotic slogans; the atmosphere is festive.', 'It is a unique blend of patriotism and spectacle.', 'Arrive early; bags and cameras may be checked by security.', 'Bring snacks and water; facilities are basic.', 'Flag and souvenir sellers near the parking area.', 'Arrive an hour before sunset. Carry your ID.', 'Ceremony daily before sunset.', 'Free.', 'October to March', true),
  ('data-darbar', 'Data Darbar', 'religious', 'Lahore', 'Punjab', 31.5788, 74.3035, 400, 76, 'Shrine of the 11th-century Sufi saint Ali Hujwiri, Lahore''s spiritual heart.', 'Data Darbar is the shrine of Ali Hujwiri, known as Data Ganj Bakhsh, and one of the most visited Sufi shrines in South Asia.', 'Ali Hujwiri authored the Kashf al-Mahjub, a classic Persian treatise on Sufism, and died in Lahore in the 11th century.', 'Devotees offer prayers, distribute food (langar) and listen to qawwali.', 'It is central to Lahore''s Sufi heritage and draws visitors of all backgrounds.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times. Separate entrances may exist for men and women.', 'Free langar is distributed; street food around Bhati Gate.', 'Prayer beads, rose petals and religious books.', 'Thursday evenings feature qawwali; expect crowds.', 'Open 24 hours.', 'Free.', 'Year-round', true),
  ('liberty-market', 'Liberty Market', 'shopping', 'Lahore', 'Punjab', 31.5104, 74.3445, 500, 70, 'Popular Gulberg market for clothes, fabrics and street snacks.', 'A modern shopping hub in Gulberg known for women''s clothing, designer lawn, jewellery and food stalls around a central roundabout.', 'Developed in the 1960s as Gulberg grew into a planned residential area.', 'Evening shopping and snacks are a family outing for many Lahoris.', 'A good contrast to the old city bazaars.', 'Fixed prices in branded stores; bargaining at stalls.', 'Fresh juice, chaat and fast food.', 'Lawn fabric, shoes, jewellery and accessories.', 'Parking is tight in the evening; use ride-hailing.', 'Roughly noon to 10 PM.', 'Free.', 'Evenings', true),
  ('faisal-mosque', 'Faisal Mosque', 'religious', 'Islamabad', 'Islamabad Capital Territory', 33.7295, 73.0372, 1000, 97, 'Iconic tent-shaped national mosque at the foot of the Margalla Hills.', 'With its tent-like concrete shell and four pencil-thin minarets, Faisal Mosque is the national mosque of Pakistan and one of the largest mosques in the world.', 'Designed by Turkish architect Vedat Dalokay and completed in 1986, funded largely by a gift from King Faisal of Saudi Arabia.', 'Its modern design breaks from traditional domes and is inspired by a Bedouin tent.', 'It is the defining landmark of Islamabad and a centre of national religious life.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times.', 'Food kiosks near the parking area; F-7 Jinnah Super has restaurants.', 'Islamic books and prayer items at stalls near the entrance.', 'Visit at sunset for views against the Margalla Hills.', 'Daily; tourist access outside prayer times.', 'Free.', 'Year-round', true),
  ('pakistan-monument', 'Pakistan Monument', 'cultural', 'Islamabad', 'Islamabad Capital Territory', 33.6931, 73.0689, 700, 86, 'Flower-shaped national monument on Shakarparian hill with a museum.', 'The Pakistan Monument has four large petals representing the provinces and three smaller ones for the territories, with murals of national history on the inner walls.', 'Completed in 2007 and designed by architect Arif Masoud.', 'Murals depict the Pakistan Movement and figures such as Jinnah and Iqbal.', 'It symbolises national unity.', 'Respect the monument; no climbing.', 'Cafes on site and at nearby Lok Virsa.', 'The museum shop sells books and souvenirs.', 'Combine with Lok Virsa Museum next door (overlapping radius).', 'Daily, about 9 AM to 9 PM.', 'Ticketed for the museum.', 'Evenings, year-round', true),
  ('lok-virsa-museum', 'Lok Virsa Heritage Museum', 'museum', 'Islamabad', 'Islamabad Capital Territory', 33.6889, 73.0738, 400, 74, 'Folk heritage museum of Pakistan''s crafts, costumes and music.', 'Lok Virsa showcases the living folk traditions of Pakistan''s regions with dioramas, embroidery, musical instruments and woodwork.', 'Established as the National Institute of Folk and Traditional Heritage in 1974.', 'Regular craft festivals bring artisans from across the country.', 'The best single overview of Pakistan''s regional cultures.', 'Photography may be restricted in some halls.', 'Food stalls during festivals.', 'Handicrafts shop with authentic regional crafts.', 'Check for the annual Lok Mela festival.', 'About 10 AM to 6 PM, closed Mondays.', 'Ticketed (low fee).', 'Year-round', true),
  ('daman-e-koh', 'Daman-e-Koh Viewpoint', 'viewpoint', 'Islamabad', 'Islamabad Capital Territory', 33.7397, 73.0566, 500, 82, 'Hilltop garden with panoramic views over Islamabad.', 'A terraced viewpoint in the Margalla Hills offering sweeping views of Islamabad, Faisal Mosque and Rawal Lake.', 'Developed as a public viewpoint as Islamabad was planned in the 1960s.', 'A favourite family spot, with monkeys in the trees.', 'The best panoramic view of the planned capital.', 'Do not feed the monkeys.', 'Snack kiosks and a cafe on site.', 'Few shops.', 'Clear days after rain give the best views.', 'Daily, morning to late evening.', 'Free.', 'Year-round', true),
  ('saidpur-village', 'Saidpur Village', 'cultural', 'Islamabad', 'Islamabad Capital Territory', 33.7411, 73.07, 400, 70, 'Restored centuries-old village at the foot of the Margalla Hills.', 'A historic village with restored stone houses, a Hindu temple, a gurdwara and restaurants set against the hills.', 'Named after Sultan Said Khan of the Gakhar tribe in the 16th century; the village was a site of religious diversity.', 'Shows the shared Hindu, Sikh and Muslim heritage of the area.', 'A good place to understand the pre-Islamabad history.', 'Respect places of worship.', 'Traditional restaurants serving desi food.', 'Small craft shops.', 'Pleasant in the evening; combine with Trail 3.', 'Restaurants open late.', 'Free.', 'Year-round', true),
  ('rawal-lake', 'Rawal Lake', 'nature', 'Islamabad', 'Islamabad Capital Territory', 33.7032, 73.1236, 1200, 68, 'Reservoir with lakeside gardens, boating and sunset views.', 'An artificial reservoir that supplies water to Rawalpindi, surrounded by terraced gardens, picnic spots and boating points.', 'Formed by a dam on the Korang river completed in 1962.', 'Families come for picnics and boat rides.', 'A calm natural escape close to the city.', 'Swimming is not allowed.', 'Snack stalls at the view point.', 'None.', 'Sunset from the lake view park is beautiful.', 'Daily, morning to evening.', 'Small entry fee to the lake view park.', 'Spring and autumn', true),
  ('margalla-trail-3', 'Margalla Hills Trail 3', 'nature', 'Islamabad', 'Islamabad Capital Territory', 33.7381, 73.0839, 500, 66, 'Popular hiking trail climbing to viewpoints in Margalla Hills National Park.', 'A steep, well-used trail starting in F-6 that climbs through forest to viewpoints and continues towards Pir Sohawa.', 'Part of Margalla Hills National Park, established in 1980.', 'Early morning hikes are a local tradition.', 'Shows the biodiversity of the Himalayan foothills.', 'Stay on the trail; carry water and avoid hiking alone at dusk.', 'Bring your own snacks.', 'None.', 'Start early in summer to avoid heat.', 'Open from dawn; avoid after dark.', 'Free.', 'October to April', true),
  ('raja-bazaar', 'Raja Bazaar', 'shopping', 'Rawalpindi', 'Punjab', 33.6155, 73.0634, 500, 60, 'Rawalpindi''s busiest traditional market for everything from spices to fabric.', 'A dense, historic market district of narrow lanes selling spices, cloth, utensils, dry fruit and street food.', 'One of the oldest markets of Rawalpindi, dating back to the 19th century.', 'Bargaining is the norm.', 'A lively look at old Rawalpindi.', 'Keep valuables secure; traffic is chaotic.', 'Chana chaat and fresh jalebi.', 'Spices, dry fruit, fabrics and household goods.', 'Visit before noon to avoid the worst crowds.', 'Roughly 10 AM to 9 PM.', 'Free.', 'Year-round', true),
  ('taxila-museum', 'Taxila Museum', 'museum', 'Taxila', 'Punjab', 33.7461, 72.8378, 800, 72, 'Gandhara civilisation treasures near the UNESCO ruins of Taxila.', 'The museum displays Buddhist sculpture, coins, jewellery and pottery excavated from the ancient city of Taxila.', 'Taxila was a major centre of learning and trade on the Silk Road; the ruins are a UNESCO World Heritage Site since 1980.', 'Gandhara art blends Greek, Persian and Indian styles.', 'Key to understanding Buddhist heritage in Pakistan.', 'Photography may be restricted inside.', 'Small cafes on the road outside.', 'Replica Gandhara sculptures sold nearby.', 'Combine with the Dharmarajika and Sirkap ruins.', 'About 9 AM to 5 PM.', 'Ticketed.', 'October to March', true),
  ('mazar-e-quaid', 'Mazar-e-Quaid', 'historical', 'Karachi', 'Sindh', 24.875, 67.04, 800, 94, 'White marble mausoleum of Muhammad Ali Jinnah, the founder of Pakistan.', 'The Mazar-e-Quaid is a white marble mausoleum with Moorish arches set in a large garden, housing the tomb of Muhammad Ali Jinnah.', 'Completed in 1970 and designed by Yahya Merchant.', 'A ceremonial guard change takes place on national days.', 'The most important national monument of Pakistan.', 'Dress respectfully and keep silent inside the tomb chamber.', 'Food stalls outside the garden.', 'Flags and souvenirs at the gate.', 'Visit in the evening when it is lit up.', 'Daily, about 9 AM to evening.', 'Free.', 'November to February', true),
  ('clifton-beach', 'Clifton Beach (Sea View)', 'nature', 'Karachi', 'Sindh', 24.786, 67.035, 1500, 85, 'Karachi''s main beach promenade with camel rides and sea breeze.', 'A long Arabian Sea beachfront popular for evening walks, camel and horse rides and snacks.', 'Clifton grew as a seaside resort in the colonial era.', 'Families come in the evening, especially on weekends.', 'The city''s favourite public space by the sea.', 'Swimming is dangerous during the monsoon; follow warnings.', 'Corn on the cob, chaat and fresh coconut water.', 'Small toy and souvenir sellers.', 'Large radius (1.5 km) for testing; avoid the water during rough seas.', 'Open 24 hours.', 'Free.', 'November to March', true),
  ('mohatta-palace', 'Mohatta Palace', 'museum', 'Karachi', 'Sindh', 24.8135, 67.0333, 400, 70, 'Pink sandstone palace turned museum in Clifton.', 'An elegant palace of pink Jodhpur stone with domes and balconies, now a museum hosting art and heritage exhibitions.', 'Built in 1927 as the summer home of businessman Shivratan Mohatta.', 'Rajput-style architecture in Karachi.', 'A rare surviving example of pre-partition grandeur.', 'Photography rules vary by exhibition.', 'Cafes in Clifton nearby.', 'Museum shop with books and crafts.', 'Check current exhibitions before visiting.', 'About 11 AM to 6 PM, closed Mondays.', 'Ticketed.', 'Year-round', true),
  ('frere-hall', 'Frere Hall', 'historical', 'Karachi', 'Sindh', 24.8473, 67.0329, 400, 68, 'Victorian Gothic hall with gardens, a library and a weekend book market.', 'Frere Hall is a colonial-era building with Venetian Gothic style, housing a library and a gallery with Sadequain murals.', 'Completed in 1865 and named after Sir Bartle Frere, a commissioner of Sindh.', 'A weekend book bazaar is held in the garden.', 'A reminder of colonial Karachi''s architecture.', 'Respect library rules.', 'Food streets in Saddar nearby.', 'Second-hand books at the Sunday market.', 'Sundays are best for the book market.', 'Daily, about 8 AM to 6 PM.', 'Free.', 'Year-round', true),
  ('burns-road-food-street', 'Burns Road Food Street', 'food', 'Karachi', 'Sindh', 24.8575, 67.0125, 400, 80, 'Karachi''s legendary street of nihari, biryani and rabri.', 'A historic street lined with decades-old eateries serving Karachi favourites, from nihari and haleem to biryani and kulfi.', 'Many restaurants trace their roots to families who migrated in 1947.', 'Food is shared and eaten late at night.', 'The heart of Karachi''s street food culture.', 'Expect crowds and simple seating.', 'Nihari, biryani, haleem, fried fish, rabri and kulfi.', 'Few souvenirs; it is all about food.', 'Go hungry and try several shops.', 'Most stalls open evening to late night.', 'Free; budget-friendly food.', 'Evenings', true),
  ('port-grand', 'Port Grand', 'attraction', 'Karachi', 'Sindh', 24.8389, 66.98, 500, 66, 'Waterfront food and entertainment complex on an old harbour bridge.', 'A promenade of restaurants and stalls built along a disused bridge in the Karachi harbour, with views of the port.', 'Opened in 2011 on the old Native Jetty Bridge.', 'A popular evening destination for families and friends.', 'Shows Karachi''s identity as a port city.', 'Entry may require a ticket.', 'Wide range of restaurants.', 'Small souvenir kiosks.', 'Best after sunset.', 'Evenings to late night.', 'Ticketed entry.', 'Evenings', true),
  ('empress-market', 'Empress Market', 'shopping', 'Karachi', 'Sindh', 24.8604, 67.0294, 400, 62, 'Colonial clock-tower market for spices, dry fruit and produce.', 'A Victorian market building with a tall clock tower in Saddar, selling spices, dry fruit, meat, fabric and household goods.', 'Built in the 1880s and named after Queen Victoria, Empress of India.', 'Bargaining is expected.', 'One of Karachi''s best-known colonial landmarks.', 'Keep valuables secure.', 'Street food around Saddar.', 'Spices, dry fruit and tea.', 'Morning is the best time to see the market active.', 'About 9 AM to 9 PM.', 'Free.', 'Year-round', true),
  ('murree-mall-road', 'Murree Mall Road', 'shopping', 'Murree', 'Punjab', 33.907, 73.3943, 1000, 82, 'Hill station promenade with pine forests and mountain views.', 'The pedestrian Mall Road is the centre of Murree hill station, lined with shops, cafes and colonial buildings.', 'Murree was founded as a British sanatorium in the 1850s.', 'A favourite summer escape from the plains.', 'Pakistan''s most visited hill station.', 'Roads can close in heavy snow; check alerts before travelling.', 'Chapli kebab, corn and hot tea.', 'Shawls, woollens and wooden crafts.', 'Avoid peak snowfall weekends unless roads are confirmed open.', 'Shops open late in season.', 'Free.', 'April to October', true),
  ('lake-saiful-muluk', 'Lake Saiful Muluk', 'nature', 'Naran', 'Khyber Pakhtunkhwa', 34.877, 73.6936, 3000, 90, 'Alpine lake below Malika Parbat, wrapped in folklore.', 'A turquoise high-altitude lake in the Kaghan Valley reached by jeep from Naran, surrounded by snow-capped peaks.', 'The lake is linked to the legend of Prince Saif-ul-Malook and the fairy princess Badri-ul-Jamala.', 'Storytellers recount the fairy tale by the shore.', 'One of Pakistan''s most famous natural sights.', 'Weather changes quickly; carry warm clothing.', 'Tea and pakoras at shore-side stalls.', 'Few shops.', 'Large radius (3 km) suits mountain areas with weak GPS.', 'Accessible roughly May to October.', 'Jeep fare from Naran.', 'June to September', true),
  ('baltit-fort', 'Baltit Fort', 'historical', 'Karimabad, Hunza', 'Gilgit-Baltistan', 36.3254, 74.6697, 800, 88, 'Centuries-old fort overlooking the Hunza valley.', 'Perched above Karimabad, Baltit Fort is a restored mountain fort and museum with views of Rakaposhi and Ultar peaks.', 'Its foundations date back around 700 years; it was the seat of the Mirs of Hunza and was restored in the 1990s.', 'Tibetan-influenced architecture reflects ties across the Karakoram.', 'A symbol of Hunza''s heritage.', 'Guided tours are mandatory inside.', 'Try apricot cake and walnut bread in Karimabad.', 'Gemstones, handwoven rugs and dry apricots.', 'Combine with Altit Fort.', 'About 9 AM to 5:30 PM.', 'Ticketed.', 'April to October', true),
  ('altit-fort', 'Altit Fort', 'historical', 'Altit, Hunza', 'Gilgit-Baltistan', 36.3171, 74.6826, 600, 76, 'The oldest fort in Hunza, above the Hunza river gorge.', 'Altit Fort sits on a cliff above the Hunza river with royal gardens and an old settlement below.', 'Believed to be around 900 years old and older than Baltit Fort.', 'Restored with a women''s community initiative.', 'A key monument of the Silk Road valleys.', 'Guided tours inside.', 'Cafe in the royal garden.', 'Local crafts at the gate.', 'Close to Baltit Fort: overlapping-region test.', 'About 9 AM to 5:30 PM.', 'Ticketed.', 'April to October', true),
  ('attabad-lake', 'Attabad Lake', 'nature', 'Gojal, Hunza', 'Gilgit-Baltistan', 36.33, 74.865, 3000, 89, 'Turquoise lake formed by a landslide on the Karakoram Highway.', 'A striking blue lake in upper Hunza created when a massive landslide blocked the Hunza river, now popular for boating.', 'The lake formed after the landslide of January 2010, which submerged villages and part of the Karakoram Highway.', 'Locals rebuilt with tunnels and tourism businesses.', 'A powerful example of nature reshaping the region.', 'Wear life jackets on boats.', 'Trout and chai at lakeside cafes.', 'Few shops.', 'Check landslide alerts on the KKH before travelling.', 'Daylight hours.', 'Free; boat rides paid.', 'May to October', true),
  ('passu-cones', 'Passu Cones Viewpoint', 'viewpoint', 'Passu, Hunza', 'Gilgit-Baltistan', 36.46, 74.89, 3000, 80, 'Cathedral-like spires of Tupopdan peak above the KKH.', 'The jagged Passu Cones are one of the most photographed views in Pakistan, rising above the Karakoram Highway.', 'Tupopdan peak is part of the Karakoram range.', 'Wakhi culture predominates in Gojal.', 'Iconic Karakoram scenery.', 'Do not stop on dangerous road bends.', 'Simple cafes in Passu.', 'None.', 'Sunrise and sunset light are best.', 'Always open.', 'Free.', 'May to October', true),
  ('khunjerab-pass', 'Khunjerab Pass', 'viewpoint', 'Khunjerab', 'Gilgit-Baltistan', 36.85, 75.428, 3000, 78, 'High-altitude border crossing on the Karakoram Highway.', 'At about 4,700 metres, Khunjerab is one of the highest paved border crossings in the world, on the Pakistan-China border.', 'The Karakoram Highway over the pass opened in the 1980s.', 'Part of Khunjerab National Park.', 'A landmark of engineering and the old Silk Road.', 'Altitude sickness is possible; move slowly.', 'Carry snacks; options are very limited.', 'None.', 'Go early; weather changes fast.', 'Usually open May to November.', 'National park fee.', 'June to September', true),
  ('shangrila-skardu', 'Shangrila Resort (Lower Kachura Lake)', 'nature', 'Skardu', 'Gilgit-Baltistan', 35.4206, 75.4475, 1500, 80, 'Lakeside resort known as Heaven on Earth near Skardu.', 'Lower Kachura Lake, home to the Shangrila Resort, is a calm lake ringed by orchards and mountains.', 'The resort was developed in the 1980s and gained fame for its pagoda-style buildings.', 'Balti culture predominates in Skardu.', 'Gateway to the high peaks of the Karakoram.', 'Respect private resort areas.', 'Trout and apricot dishes.', 'Dry fruit and gemstones in Skardu bazaar.', 'Combine with Upper Kachura Lake.', 'Daylight hours.', 'Small entry fee to the resort.', 'May to October', true),
  ('fairy-meadows', 'Fairy Meadows', 'nature', 'Diamer', 'Gilgit-Baltistan', 35.3864, 74.5861, 3000, 84, 'Alpine meadow with a direct view of Nanga Parbat.', 'A grassy plateau reached by jeep and trek from Raikot Bridge, offering views of the 8,126 m Nanga Parbat.', 'Named by German climbers; the base camp of Nanga Parbat''s Rakhiot face is nearby.', 'Cabins and camping run by locals.', 'One of the most dramatic mountain views on Earth.', 'The jeep road is dangerous; use local drivers.', 'Simple meals in camps.', 'None.', 'Bring warm layers even in summer.', 'Season roughly May to October.', 'Jeep and camping charges.', 'June to September', true),
  ('qissa-khwani-bazaar', 'Qissa Khwani Bazaar', 'shopping', 'Peshawar', 'Khyber Pakhtunkhwa', 34.0083, 71.5786, 500, 72, 'The storytellers'' bazaar at the heart of old Peshawar.', 'Historic market where travellers and traders once gathered to hear stories over tea, now full of tea houses and dry fruit shops.', 'Peshawar is one of the oldest living cities in South Asia and a historic caravan stop near the Khyber Pass.', 'Green tea (kahwa) and hospitality are central to Pashtun culture.', 'A living piece of Silk Road history.', 'Dress conservatively; ask before photographing people.', 'Chapli kebab and kahwa.', 'Dry fruit, Peshawari chappals and copperware.', 'Combine with Mahabat Khan Mosque.', 'Roughly 10 AM to 9 PM.', 'Free.', 'October to March', true),
  ('mahabat-khan-mosque', 'Mahabat Khan Mosque', 'religious', 'Peshawar', 'Khyber Pakhtunkhwa', 34.0089, 71.5725, 300, 64, '17th-century Mughal mosque with painted interiors in old Peshawar.', 'A white Mughal mosque with tall minarets and finely painted floral interiors in the heart of the Walled City.', 'Built in the 1670s during the governorship of Mahabat Khan.', 'An active community mosque.', 'Peshawar''s finest Mughal monument.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times.', 'Street food around Qissa Khwani.', 'Spice and cloth markets nearby.', 'Visit outside prayer times.', 'Daily outside prayer times.', 'Free.', 'October to March', true),
  ('shah-rukn-e-alam', 'Tomb of Shah Rukn-e-Alam', 'religious', 'Multan', 'Punjab', 30.2005, 71.472, 800, 78, 'Massive octagonal brick tomb, a masterpiece of Multani tilework.', 'This 14th-century octagonal mausoleum of the Sufi saint Shah Rukn-e-Alam dominates Multan''s skyline with its blue-tiled brick walls.', 'Built in the early 14th century during the Tughlaq period.', 'Multan is called the City of Saints for its many shrines.', 'One of the earliest examples of Tughlaq architecture.', 'Dress modestly: cover shoulders and knees; women should carry a scarf. Remove shoes before entering prayer areas and keep voices low, especially during prayer times.', 'Sohan halwa is the famous local sweet.', 'Blue pottery and camel-skin lamps.', 'Avoid the midday summer heat.', 'Open daily.', 'Free.', 'November to February', true),
  ('mohenjo-daro', 'Mohenjo-daro', 'historical', 'Larkana', 'Sindh', 27.329, 68.1386, 1500, 85, 'UNESCO ruins of one of the world''s earliest planned cities.', 'The ruins of a Bronze Age Indus Valley city with grid streets, drainage, the Great Bath and a Buddhist stupa.', 'Built around 2500 BCE and rediscovered in the 1920s; a UNESCO World Heritage Site since 1980.', 'The Indus civilisation had advanced urban planning and trade.', 'A cornerstone of world archaeology.', 'Do not climb on fragile walls.', 'Limited food; carry water.', 'Replica seals at the museum shop.', 'Visit in winter; summers are extremely hot.', 'Daily, about 8 AM to 5 PM.', 'Ticketed.', 'November to February', true),
  ('rohtas-fort', 'Rohtas Fort', 'historical', 'Jhelum', 'Punjab', 32.963, 73.577, 1200, 70, 'Massive 16th-century garrison fort, a UNESCO World Heritage Site.', 'Rohtas Fort''s huge stone walls and gates stretch for kilometres across the hills near Jhelum.', 'Built by Sher Shah Suri in the 1540s to block the return of the Mughal emperor Humayun.', 'A fusion of Afghan and Persian military architecture.', 'An outstanding example of early Muslim military architecture.', 'Wear sturdy shoes.', 'Few options; bring snacks.', 'None.', 'Allow a half day.', 'Daily during daylight.', 'Ticketed.', 'October to March', true),
  ('katas-raj-temples', 'Katas Raj Temples', 'cultural', 'Chakwal', 'Punjab', 32.724, 72.951, 600, 60, 'Ancient Hindu temple complex around a sacred pond.', 'A complex of temples built around a pond considered sacred in Hindu tradition, in the Salt Range.', 'Temples date from the 7th century onwards; the site is linked to legends of the Mahabharata.', 'Pilgrims visit during festivals.', 'A key site of Pakistan''s religious diversity.', 'Respect worship areas.', 'Limited food nearby.', 'None.', 'Combine with the Salt Range drive.', 'Daily during daylight.', 'Free or low fee.', 'October to March', true)
