insert into public.road_alerts (title, description, alert_type, severity, region, city, latitude, longitude, radius_m, ends_at) values
  ('Dense fog on Murree Expressway', 'Visibility below 50 m reported between Bhara Kahu and Murree. Drive slowly with fog lights.', 'fog', 'high', 'Punjab', 'Murree', 33.86, 73.32, 15000, now() + interval '3 days'),
  ('Snowfall: chains advised in Murree', 'Fresh snowfall on Mall Road access roads. Tyre chains recommended; avoid travel after dark.', 'snow', 'medium', 'Punjab', 'Murree', 33.907, 73.3943, 8000, now() + interval '5 days'),
  ('Landslide near Attabad tunnels (KKH)', 'Debris on the Karakoram Highway near the Attabad tunnels. One lane open; expect delays.', 'landslide', 'critical', 'Gilgit-Baltistan', 'Hunza', 36.34, 74.88, 10000, now() + interval '2 days'),
  ('Babusar Pass closed', 'Babusar Top road closed for the season due to snow. Use the KKH via Besham.', 'closure', 'high', 'Khyber Pakhtunkhwa', 'Naran', 35.15, 74.05, 30000, now() + interval '60 days'),
  ('Smog advisory in Lahore', 'Air quality is very unhealthy. Limit outdoor activity and wear a mask.', 'smog', 'high', 'Punjab', 'Lahore', 31.5497, 74.3436, 25000, now() + interval '7 days'),
  ('M-2 Motorway fog (Lahore-Islamabad)', 'Sections of the M-2 may close at night due to fog. Check before departure.', 'fog', 'medium', 'Punjab', null, 32.4, 73.3, 60000, now() + interval '5 days'),
  ('Urban flooding in Karachi', 'Heavy rain has flooded underpasses in Saddar and Clifton. Avoid low-lying roads.', 'flood', 'high', 'Sindh', 'Karachi', 24.86, 67.03, 12000, now() + interval '2 days'),
  ('Heavy rain warning for Islamabad', 'Thunderstorms expected this evening. Margalla trails may be slippery.', 'rain', 'medium', 'Islamabad Capital Territory', 'Islamabad', 33.71, 73.06, 15000, now() + interval '1 days'),
  ('Traffic diversion near Mall Road, Lahore', 'Event-related diversion around Charing Cross. Allow extra time.', 'traffic', 'low', 'Punjab', 'Lahore', 31.558, 74.328, 3000, now() + interval '1 days'),
  ('Rockfall risk on Naran-Lake Saiful Muluk jeep track', 'Loose rocks after rain. Travel with experienced local drivers only.', 'landslide', 'medium', 'Khyber Pakhtunkhwa', 'Naran', 34.89, 73.68, 6000, now() + interval '3 days');
