-- GoTourGo demo seed data (Pakistan-wide). Generated; safe to re-run.
-- Landmarks use real coordinates and mixed geofence radii (300 m to 3 km) so the
-- proximity system can be tested with different scenarios.
-- image_url is left null: add licensed image URLs later, for example:
--   update public.destinations set image_url = 'https://...' where slug = 'badshahi-mosque';

begin;

on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  city = excluded.city,
  region = excluded.region,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  radius_m = excluded.radius_m,
  popularity = excluded.popularity,
  short_description = excluded.short_description,
  description = excluded.description,
  history = excluded.history,
  culture = excluded.culture,
  significance = excluded.significance,
  local_customs = excluded.local_customs,
  food = excluded.food,
  shopping = excluded.shopping,
  tips = excluded.tips,
  opening_hours = excluded.opening_hours,
  entry_fee = excluded.entry_fee,
  best_time = excluded.best_time,
  is_landmark = excluded.is_landmark;

on conflict (destination_id, locale) do update set name = excluded.name, short_description = excluded.short_description;

delete from public.nearby_services;

delete from public.road_alerts where source = 'GoTourGo demo data';

commit;
